() => {
  // Click the visible element whose text matches "Skip" (mode "exact": exact | prefix | contains), right panel first.
  const want = "Skip", mode = "exact";
  const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const vis = (e) => { const r = e.getBoundingClientRect(); const cs = getComputedStyle(e); return r.width > 0 && r.height > 0 && cs.visibility !== 'hidden' && cs.display !== 'none' && r.bottom > 0 && r.top < innerHeight; };
  const match = (s) => (mode === 'exact' ? s === want : mode === 'prefix' ? s.startsWith(want) : s.includes(want));
  const rank = { BUTTON: 0, A: 1, INPUT: 1, LABEL: 2 };
  const all = [...document.querySelectorAll('button,a,[role=button],[role=option],[role=radio],[role=tab],[role=menuitem],label,li,[tabindex],div,span,p')]
    .filter((e) => vis(e) && match(txt(e.innerText || e.getAttribute('aria-label') || e.value)));
  if (!all.length) return 'NOT FOUND: ' + want;
  all.sort((a, b) => (a.innerText.length - b.innerText.length) || ((rank[a.tagName] ?? 3) - (rank[b.tagName] ?? 3)));
  const el = all[0].closest('button,a,[role=button],[role=option],[role=radio],[role=tab],label') || all[0];
  if (el.disabled || el.getAttribute('aria-disabled') === 'true') return 'DISABLED: ' + txt(el.innerText).slice(0, 60);
  el.scrollIntoView({ block: 'center' });
  el.click();
  return 'clicked: ' + txt(el.innerText || el.getAttribute('aria-label')).slice(0, 70) + ' <' + el.tagName + '>';
}

async () => {
  // Read-only probe: DOM summary + scene getters. Never calls setters.
  const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const out = { url: location.pathname + location.search };
  const body = txt(document.body.innerText);
  const price = body.match(/Total List Price\s*\$[\d,]+(\.\d+)?/);
  out.price = price ? price[0].replace('Total List Price', '').trim() : null;
  out.step = txt(document.querySelector('[aria-current="page"]')?.innerText) || null;
  out.dialogs = [...document.querySelectorAll('[role="dialog"],[role="alertdialog"]')].map((d) => txt(d.innerText).slice(0, 160));
  out.alerts = [...document.querySelectorAll('[role="alert"],[role="status"],[class*="toast" i],[class*="tooltip" i]')].map((d) => txt(d.innerText)).filter(Boolean).slice(0, 5);
  const w = document.querySelector('iframe')?.contentWindow;
  const api = w?.ConfiguratorAPI;
  out.sceneReady = !!api?.composition;
  if (!api) return out;
  const pick = (o, keys) => Object.fromEntries(keys.filter((k) => o && o[k] !== undefined).map((k) => [k, o[k]]));
  try {
    const all = api.composition.getAllProducts?.() ?? {};
    const order = api.composition.getOrderProductIds?.() ?? null;
    out.order = order ? JSON.stringify(order).slice(0, 200) : null;
    const KEEP = ['CabinetType', 'productType', 'Width', 'Depth', 'Height', 'DrawerStyle', 'Style', 'Handle', 'HandleType', 'CabinetColor', 'HandleGrooveColor', 'LegColor', 'CabinetPattern', 'DrawerPanelFluting', 'LateralPanelSide', 'Series', 'SidePanel', 'SidePanels', 'sinkType', 'SinkType', 'CountertopColor', 'CountertopMaterial', 'Thickness', 'BasinStyle', 'VesselColor'];
    out.products = Object.entries(all).slice(0, 10).map(([id, cfg]) => {
      const c = cfg?.config ?? cfg ?? {};
      const kept = Object.fromEntries(Object.entries(c).filter(([k]) => KEEP.some((x) => k.toLowerCase() === x.toLowerCase())));
      return { id: id.slice(0, 36), n: Object.keys(c).length, cfg: kept };
    });
  } catch (e) { out.productsErr = String(e).slice(0, 200); }
  try {
    const ct = await api.countertop.getState();
    out.countertop = pick(ct, ['productId', 'placementState', 'attached', 'moved', 'canResize', 'thickness', 'autoLength', 'customLength', 'size', 'lengthLimitsM', 'offset']);
  } catch (e) { out.ctErr = String(e).slice(0, 200); }
  try { const cv = await api.cabinetCover.getState(); out.coverEntries = cv?.service?.entries?.length ?? null; } catch (e) { out.coverErr = String(e).slice(0, 120); }
  return out;
}

() => {
  // Read-only: option-like controls in the right panel (by screen region) with selected/disabled state.
  const txt = (s) => (s || '').replace(/\s+/g, ' ').trim();
  const minX = innerWidth * 0.62;
  const vis = (e) => { const r = e.getBoundingClientRect(); return r.width > 0 && r.height > 0 && r.left >= minX && getComputedStyle(e).visibility !== 'hidden'; };
  const sel = 'button,[role=button],[role=radio],[role=option],[role=tab],[role=checkbox],[role=switch],input,select,[aria-pressed],[aria-checked],[aria-selected]';
  const items = [...document.querySelectorAll(sel)].filter(vis).map((e) => {
    const label = txt(e.getAttribute('aria-label') || e.innerText || e.value || e.title || e.closest('label')?.innerText || e.querySelector('img')?.alt);
    const selected = e.getAttribute('aria-pressed') === 'true' || e.getAttribute('aria-checked') === 'true' || e.getAttribute('aria-selected') === 'true' || e.checked === true || /(^|[-_ ])(active|selected|checked|current)([-_ A-Z]|$)/.test(e.className || '');
    const disabled = e.disabled === true || e.getAttribute('aria-disabled') === 'true' || /disabled/i.test(e.className || '');
    return (selected ? '[x] ' : '[ ] ') + (disabled ? '(disabled) ' : '') + (e.type === 'number' ? `number=${e.value} ` : '') + label.slice(0, 80);
  }).filter((s) => s.length > 4);
  const texts = [...document.querySelectorAll('h1,h2,h3,h4,h5,legend,p,span')].filter(vis).map((e) => txt(e.innerText)).filter((s) => s && s.length < 60 && /^[A-Z]/.test(s));
  return { header: txt([...document.querySelectorAll('button,div')].find((e) => /^Select /.test(txt(e.innerText)) && txt(e.innerText).length < 40)?.innerText), labels: [...new Set(texts)].slice(0, 40), controls: [...new Set(items)].slice(0, 150) };
}

